/* Momento — site styles */
:root {
  --bg: #0f1117;
  --panel: #161b22;
  --border: #30363d;
  --text: #c9d1d9;
  --muted: #8b949e;
  --accent: #79c0ff;
  --danger: #ff5f57;
  --warn: #d29922;
  --success: #3fb950;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 16px; scroll-behavior: smooth; }

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  padding: 1rem;
  max-width: 42rem;
  margin: 0 auto;
}

a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

.nav { margin-bottom: 1.5rem; }
.nav nav { display: flex; flex-wrap: wrap; gap: 0.5rem; align-items: center; }
.nav p { margin-left: auto; color: var(--muted); font-size: 0.85rem; }

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1.25rem;
  margin-bottom: 1rem;
}

.panel h1 { font-size: 1.5rem; margin-bottom: 0.5rem; }
.panel h2 { font-size: 1.15rem; margin-bottom: 0.75rem; color: var(--accent); }

.status { display: grid; grid-template-columns: max-content 1fr; gap: 0.25rem 1rem; }
.status dt { color: var(--muted); font-size: 0.85rem; }
.status dd { font-weight: 600; font-size: 0.95rem; display: flex; align-items: center; gap: 0.5rem; flex-wrap: wrap; }

.copy-button {
  background: var(--border);
  color: var(--text);
  border: none;
  border-radius: 4px;
  padding: 0.15rem 0.5rem;
  font-size: 0.75rem;
  cursor: pointer;
  transition: background 0.15s;
}
.copy-button:hover { background: #444c56; }
.copy-button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

.countdown { text-align: center; margin: 1rem 0; }
#countdown { font-size: 2rem; font-variant-numeric: tabular-nums; font-weight: 700; }
.countdown-bar { height: 6px; background: var(--border); border-radius: 3px; overflow: hidden; margin-top: 0.5rem; }
.countdown-bar-fill { height: 100%; width: 0%; background: #79c0ff; transition: width 1s linear, background 0.3s; }

.footer { margin-top: 2rem; text-align: center; color: var(--muted); font-size: 0.85rem; }
.footer nav { display: flex; flex-wrap: wrap; gap: 0.5rem; justify-content: center; }

.today-wakes { list-style: none; padding: 0; }
.today-wakes li { padding: 0.25rem 0; border-bottom: 1px solid var(--border); font-size: 0.9rem; }
.today-wakes li:last-child { border-bottom: none; }
.wake-past { color: var(--muted); }
.wake-current { color: var(--success); font-weight: 700; }
.wake-next { color: var(--accent); font-weight: 600; }
.wake-upcoming { color: var(--text); }

#skip-link {
  position: absolute;
  top: -100%;
  left: 0;
  background: var(--accent);
  color: var(--bg);
  padding: 0.5rem 1rem;
  z-index: 100;
  font-weight: 600;
  border-radius: 0 0 4px 0;
}
#skip-link:focus { top: 0; }

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
}


